import{_ as o,o as t,c as a,S as r}from"./chunks/framework.797d12ff.js";const h=JSON.parse('{"title":"CLI Tools","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/getting-started/cli-tools.md","filePath":"documentation/getting-started/cli-tools.md","lastUpdated":1773763125000}'),n={name:"documentation/getting-started/cli-tools.md"};function l(s,e,i,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-tools" tabindex="-1">CLI Tools <a class="header-anchor" href="#cli-tools" aria-label="Permalink to &quot;CLI Tools&quot;">​</a></h1><p>Forme projects use three command line tools. Each has a distinct role — knowing which to reach for will save you time.</p><h2 id="forme-codegen" tabindex="-1">Forme Codegen <a class="header-anchor" href="#forme-codegen" aria-label="Permalink to &quot;Forme Codegen&quot;">​</a></h2><p><a href="https://github.com/formewp/forme-codegen" target="_blank" rel="noreferrer">Forme codegen</a> is a globally installed tool for scaffolding new projects and generating boilerplate. Install it once on your machine and use it across all your Forme projects.</p><p>Typical uses:</p><ul><li>Creating a new base, plugin or theme project (<code>forme new</code>)</li><li>Generating boilerplate classes (<code>forme make</code>)</li><li>Managing your local Docker environment (<code>forme ketch</code>)</li><li>Bumping project versions and running tests (<code>forme bump</code>, <code>forme test</code>)</li></ul><p>See <a href="/documentation/getting-started/installing-codegen.html">Installing Forme Codegen</a> for setup instructions.</p><h2 id="wrangle" tabindex="-1">Wrangle <a class="header-anchor" href="#wrangle" aria-label="Permalink to &quot;Wrangle&quot;">​</a></h2><p>Wrangle is Forme&#39;s project-level command runner. Unlike forme codegen, it lives inside your project and is run from the project root.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">php</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">wrangle</span><span style="color:#BABED8;"> [command]</span></span></code></pre></div><p>It has two kinds of commands:</p><p><strong>Built-in framework commands</strong> — these come with Forme and cover project-level tasks that don&#39;t belong in a globally installed tool. For example <code>queue:run</code> for running the next job in the job queue.</p><p><strong>Custom commands</strong> — commands you write yourself for project-specific tasks. See <a href="/documentation/going-deeper/custom-commands.html">Custom Commands</a> for how to add your own.</p><blockquote><p><strong>Note:</strong> In plugin and theme projects, Wrangle requires a local WordPress test environment (<code>wp-test</code>) to be set up.</p></blockquote><h2 id="wp-cli" tabindex="-1">WP-CLI <a class="header-anchor" href="#wp-cli" aria-label="Permalink to &quot;WP-CLI&quot;">​</a></h2><p><a href="https://wp-cli.org/" target="_blank" rel="noreferrer">WP-CLI</a> is the official WordPress command line tool and should be installed globally. Forme projects include a <code>wp-cli.yml</code> in the base installation so that it is correctly configured for the project structure.</p><p>Typical uses:</p><ul><li>Managing plugins and themes</li><li>Inspecting and updating options (<code>wp option get siteurl</code>)</li><li>Database operations (<code>wp db export</code>, <code>wp search-replace</code>)</li></ul><p>WP-CLI can also be called from within a Wrangle command via Symfony Process — this avoids the limitations of calling WP-CLI from within another WP-CLI command.</p><h2 id="which-tool-should-i-use" tabindex="-1">Which tool should I use? <a class="header-anchor" href="#which-tool-should-i-use" aria-label="Permalink to &quot;Which tool should I use?&quot;">​</a></h2><table><thead><tr><th>Task</th><th>Tool</th></tr></thead><tbody><tr><td>Create a new project</td><td><code>forme codegen</code></td></tr><tr><td>Generate a class or boilerplate</td><td><code>forme codegen</code></td></tr><tr><td>Run the job queue</td><td><code>wrangle</code></td></tr><tr><td>Write a custom project command</td><td><code>wrangle</code></td></tr><tr><td>Manage WordPress (plugins, db, options)</td><td><code>wp-cli</code></td></tr><tr><td>Local Docker environment</td><td><code>forme codegen</code></td></tr></tbody></table>',21)])])}const u=o(n,[["render",l]]);export{h as __pageData,u as default};
